2	// helpers.h — shared bindings helpers + per-arch dispatch macro.
3	//
4	// Includes:
5	//   - int sg::detect_arch() forward decl (implemented in dispatch.cpp)
6	//   - SG_DISPATCH / SG_DISPATCH_CALL macros for runtime arch selection
7	//   - host-side gradient norm helpers extracted from the deleted
8	//     csrc/common/ops.cpp.
9	// =====================================================================
10	
11	#pragma once
12	
13	#include <torch/extension.h>
14	#include <cmath>
15	#include <stdexcept>
16	#include <string>
17	#include <vector>
18	
19	namespace sg {
20	
21	// ── Arch detection (impl in dispatch.cpp) ────────────────────────────
22	int detect_arch();
23	inline bool is_cuda_arch(int a) { return a == 90; }
24	inline bool is_hip_arch(int a)  { return a == 942; }
25	
26	// ── Fused (model, optimizer, arch) megakernel dispatch (impl in
27	//    dispatch.cpp). Declared here so bindings.cpp can bind &sg::fused_step.
28	void fused_step(const std::string& model, const std::string& optimizer,
29	                torch::Tensor params, torch::Tensor input,
30	                torch::Tensor grad, torch::Tensor state, float lr);
31	
32	// ── Per-arch namespace handles ───────────────────────────────────────
33	namespace sm90 {}
34	namespace gfx942 {}
35	
36	} // namespace sg
37	
38	// ── Dispatch macro: returns from enclosing function ──────────────────
39	#define SG_DISPATCH(METHOD, ...) \
40	    do { \
41	        const int sg_arch_ = ::sg::detect_arch(); \
42	        switch (sg_arch_) { \
43	            case 90:  return ::sg::sm90::METHOD(__VA_ARGS__); \
44	            case 942: return ::sg::gfx942::METHOD(__VA_ARGS__); \
45	            default: \
46	                throw std::runtime_error( \
47	                    std::string(#METHOD) + " dispatch: unsupported arch " + \
48	                    std::to_string(sg_arch_)); \
49	        } \
50	    } while (0)
51	
52	// ── Dispatch macro: same dispatch, no return ─────────────────────────
53	#define SG_DISPATCH_CALL(METHOD, ...) \
54	    do { \
55	        const int sg_arch_ = ::sg::detect_arch(); \
56	        switch (sg_arch_) { \
57	            case 90:  ::sg::sm90::METHOD(__VA_ARGS__); break; \
58	            case 942: ::sg::gfx942::METHOD(__VA_ARGS__); break; \
59	            default: \
60	                throw std::runtime_error( \
61	                    std::string(#METHOD) + " dispatch: unsupported arch " + \
62	                    std::to_string(sg_arch_)); \
63	        } \
64	    } while (0)
65	
66	namespace sg {
67	
68	// ── Boundary validation for optimizer fused-step entrypoints ─────────
69	// The Python wrappers historically owned device/dtype/shape/contiguity
70	// invariants; these binding entrypoints trusted them. A non-contiguous param
71	// view, a device/dtype mismatch between param and grad, or a shape mismatch
72	// silently corrupts the in-place fused update (the launchers index a flat
73	// pointer with the param's numel). Validate at the C++ boundary so a bad call
74	// fails loudly. `where` is the entrypoint name for the error message.
75	//
76	// We check the param against its paired grad. Optimizer-state buffers (m, v,
77	// ema, …) are allocated by the wrapper from `torch.zeros_like(param)` so they
78	// inherit the param's device/dtype/shape/contiguity; the param check is the
79	// load-bearing one. A missing/empty grad (sparse-grad fallback) is skipped —
80	// the per-op loops already filter those out before dispatch.
81	inline void check_param_grad(
82	    const torch::Tensor& p,
83	    const torch::Tensor& g,
84	    const char* where
85	) {
86	    TORCH_CHECK(p.defined(), where, ": param tensor is undefined");
87	#if defined(WITH_HIP)
88	    TORCH_CHECK(p.is_hip(), where, ": param must be on a HIP device");
89	#else
90	    TORCH_CHECK(p.is_cuda(), where, ": param must be on a CUDA device");
91	#endif
92	    // A non-contiguous param view aliases a strided storage; the fused
93	    // launchers treat data_ptr() as a dense [numel] buffer, so a strided view
94	    // would read/write the wrong elements and silently corrupt the update.
95	    TORCH_CHECK(p.is_contiguous(), where,
96	                ": param must be contiguous (got a non-contiguous view); "
97	                "call .contiguous() in the Python wrapper before the fused step");
98	    if (!g.defined() || g.numel() == 0) return;  // sparse-grad: skip (filtered)
99	    TORCH_CHECK(g.device() == p.device(), where,
100	                ": grad device (", g.device().str(),
101	                ") != param device (", p.device().str(), ")");
102	    TORCH_CHECK(g.scalar_type() == p.scalar_type(), where,
103	                ": grad dtype (", toString(g.scalar_type()),
104	                ") != param dtype (", toString(p.scalar_type()), ")");
105	    TORCH_CHECK(g.sizes() == p.sizes(), where,
106	                ": grad shape (", g.sizes(), ") != param shape (",
107	                p.sizes(), ")");
108	    TORCH_CHECK(g.is_contiguous(), where, ": grad must be contiguous");
109	}
110	
111	// Validate every (param, grad) pair in a multi-tensor fused-step entrypoint.
112	inline void check_params_grads(
113	    const std::vector<torch::Tensor>& params,
114	    const std::vector<torch::Tensor>& grads,
115	    const char* where
116	) {
117	    TORCH_CHECK(params.size() == grads.size(), where,
118	                ": params.size() (", params.size(),
119	                ") != grads.size() (", grads.size(), ")");
120	    for (size_t i = 0; i < params.size(); ++i)
121	        check_param_grad(params[i], grads[i], where);
122	}
123	
124	// ── Device-side gradient clipping: single CPU sync instead of N ──────
125	inline void clip_grad_norms_device_side(
126	    std::vector<torch::Tensor>& grads,
127	    size_t n_params,
128	    float grad_clip_norm
129	) {
130	    if (grad_clip_norm <= 0.0f) return;
131	
132	    // Collect the present grads once. Fused multi-tensor ops want a flat list.
133	    std::vector<torch::Tensor> present;
134	    present.reserve(n_params);
135	    for (size_t i = 0; i < n_params; i++) {
136	        if (grads[i].defined() && grads[i].numel() > 0)
137	            present.push_back(grads[i]);
138	    }
139	    if (present.empty()) return;
140	
141	    // Per-tensor L2 norms via a single fused multi-tensor reduction
142	    // (torch::_foreach_norm), replacing the per-tensor upcast + dot + add_
143	    // (≈2N kernel launches) with one foreach launch. Numerics: the L2 norm of
144	    // each tensor is accumulated into a fp32 sum-of-squares (squaring the
145	    // per-tensor norm == that tensor's sum-of-squares), matching the original
146	    // fp32 accumulation of the global sum-of-squares. To preserve the original
147	    // precision when grads are NOT already fp32, upcast those (only) to fp32
148	    // before the norm; fp32 grads skip the upcast entirely.
149	    bool all_fp32 = true;
150	    for (auto& g : present)
151	        if (g.scalar_type() != torch::kFloat32) { all_fp32 = false; break; }
152	
153	    std::vector<torch::Tensor> norm_inputs;
154	    if (all_fp32) {
155	        norm_inputs = present;
156	    } else {
157	        norm_inputs.reserve(present.size());
158	        for (auto& g : present)
159	            norm_inputs.push_back(g.scalar_type() == torch::kFloat32
160	                                      ? g
161	                                      : g.to(torch::kFloat32));
162	    }
163	
164	    auto norms = torch::_foreach_norm(norm_inputs, /*p=*/2);
165	    // norm_sq = sum_i (||g_i||_2)^2, accumulated in fp32 on-device, one sync.
166	    auto stacked = torch::stack(norms).to(torch::kFloat32);
167	    float total_norm =
168	        std::sqrt(stacked.dot(stacked).item<float>());
169	
170	    if (total_norm > grad_clip_norm) {
171	        float clip_coef = grad_clip_norm / (total_norm + 1e-6f);
172	        // Fused multi-tensor in-place scale of the present grads.
173	        torch::_foreach_mul_(present, clip_coef);
174	    }
175	}
176	
177	// ── Device-side SAM grad-norm: single CPU sync instead of N ──────────
178	inline float compute_sam_grad_norm_device_side(
179	    std::vector<torch::Tensor>& grads,
180	    size_t n_grads
181	) {
182	    torch::Device dev(torch::kCPU);
183	    for (size_t i = 0; i < n_grads; i++) {
184	        if (grads[i].defined() && grads[i].numel() > 0) {
185	            dev = grads[i].device();
186	            break;
187	        }
188	    }
189	    auto norm_sq = torch::zeros(
190	        {1}, torch::TensorOptions().device(dev).dtype(torch::kFloat32));
191	    for (size_t i = 0; i < n_grads; i++) {
192	        if (grads[i].defined() && grads[i].numel() > 0) {
193	            auto g_flat = grads[i].to(torch::kFloat32).reshape(-1);
194	            norm_sq.add_(g_flat.dot(g_flat));
195	        }
196	    }
197	    return std::sqrt(norm_sq.item<float>()) + 1e-12f;
198	}
199	
200	} // namespace sg
