    const int block = SG_TUNED_BLOCK_SIZE;
    const int grid = static_cast<int>(
        std::min<int64_t>(65535, (N + block - 1) / block));

    if (SG_TUNED_VEC_WIDTH == 4 && param.scalar_type() == torch::kFloat32 &&
        prim::is_vec4_alignable(param.data_ptr(), N) &&
